import Root from './scroll-spy.svelte';
import Link from './scroll-spy-link.svelte';
import Nav from './scroll-spy-nav.svelte';
import Section from './scroll-spy-section.svelte';
import Viewport from './scroll-spy-viewport.svelte';

export type { ScrollSpyChildProps, ScrollSpyProps, ScrollSpyRootProps } from './scroll-spy.svelte';
export { scrollSpyVariants } from './scroll-spy.svelte';
export type { ScrollSpyNavChildProps, ScrollSpyNavProps } from './scroll-spy-nav.svelte';
export { scrollSpyNavVariants } from './scroll-spy-nav.svelte';
export type { ScrollSpyLinkChildProps, ScrollSpyLinkProps } from './scroll-spy-link.svelte';
export type {
	ScrollSpyViewportChildProps,
	ScrollSpyViewportProps
} from './scroll-spy-viewport.svelte';
export type {
	ScrollSpySectionChildProps,
	ScrollSpySectionProps
} from './scroll-spy-section.svelte';

export {
	DEFAULT_OFFSET,
	DEFAULT_ORIENTATION,
	DEFAULT_THRESHOLD,
	getDefaultScrollBehavior,
	getScrollSpyContext,
	SCROLL_SETTLE_DELAY,
	SCROLL_SPY_ORIENTATIONS,
	ScrollSpyState,
	setScrollSpyContext,
	type ScrollSpyOrientation,
	type ScrollSpyScrollBehavior,
	type ScrollSpyStateProps
} from './scroll-spy.svelte.js';

export {
	observeSections,
	pickTopmostEntry,
	SectionRegistry,
	type SectionObserverOptions,
	type SectionRegistrySnapshot
} from './section-observer.svelte.js';

export {
	Root,
	Nav,
	Link,
	Viewport,
	Section,
	//
	Root as ScrollSpy,
	Nav as ScrollSpyNav,
	Link as ScrollSpyLink,
	Viewport as ScrollSpyViewport,
	Section as ScrollSpySection
};

import { getContext, hasContext, setContext } from 'svelte';

import type { Direction } from '$lib/components/ui/direction-provider/direction-provider.svelte.js';
import { readScrollMetrics } from '$lib/components/ui/scroller/index.js';

import { SectionRegistry } from './section-observer.svelte.js';

/** Every value `orientation` accepts, in upstream declaration order. */
export const SCROLL_SPY_ORIENTATIONS = ['horizontal', 'vertical'] as const;
export type ScrollSpyOrientation = (typeof SCROLL_SPY_ORIENTATIONS)[number];

/** Upstream `orientation = "horizontal"` (line 115). */
export const DEFAULT_ORIENTATION: ScrollSpyOrientation = 'horizontal';
/** Upstream `offset = 0` (line 111). */
export const DEFAULT_OFFSET = 0;
/** Upstream `threshold = 0.1` (line 110). */
export const DEFAULT_THRESHOLD = 0.1;
/** Upstream's 500 ms post-click suppression window (line 216). */
export const SCROLL_SETTLE_DELAY = 500;

/**
 * The DOM's `ScrollBehavior` (`"auto" | "instant" | "smooth"`), re-exported under a name the
 * `.svelte` parts can reference: the ambient DOM type is not in scope inside a Svelte module script.
 */
export type ScrollSpyScrollBehavior = ScrollBehavior;

/**
 * Upstream `getDefaultScrollBehavior` (lines 26-31): honour `prefers-reduced-motion: reduce`, and
 * fall back to `'smooth'` during SSR where no media query can be evaluated.
 */
export function getDefaultScrollBehavior(): ScrollBehavior {
	if (typeof window === 'undefined') return 'smooth';
	return window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';
}

export type ScrollSpyStateProps = {
	readonly getValue: () => string;
	readonly setValue: (value: string) => void;
	readonly getOffset: () => number;
	readonly getScrollBehavior: () => ScrollBehavior;
	readonly getScrollContainer: () => HTMLElement | null;
	readonly getOrientation: () => ScrollSpyOrientation;
	readonly getDir: () => Direction;
};

/**
 * One instance per `<ScrollSpy.Root>`, published on context. Replaces both of upstream's contexts:
 * its `StoreContext` exists only so that changing the active value re-renders the two links whose
 * state actually flips instead of the whole subtree, and Svelte's signals give that for free — a
 * link that reads `state.value` subscribes to exactly that signal (research R-02, D-3).
 */
export class ScrollSpyState {
	// $derived below is lazy at runtime (evaluated only when a member is read), but svelte-check's
	// static analysis cannot see that and flags the field as used before its constructor assignment.
	#props!: ScrollSpyStateProps;

	/** The elements eligible for passive tracking. */
	readonly sections = new SectionRegistry();

	// Upstream holds all three in refs precisely so writing them does not re-render. Making
	// `#isScrolling` reactive would tear down and re-create the observer on every click, and writing
	// it from inside that same effect would be an infinite loop (research R-04).
	#isScrolling = false;
	#settleTimeout: number | null = null;
	#lastAppliedValue: string | null = null;

	/** The single active section id every part shares (**FR-001**). */
	readonly value: string = $derived(this.#props.getValue());
	readonly orientation: ScrollSpyOrientation = $derived(this.#props.getOrientation());
	readonly dir: Direction = $derived(this.#props.getDir());
	readonly offset: number = $derived(this.#props.getOffset());
	readonly scrollBehavior: ScrollBehavior = $derived(this.#props.getScrollBehavior());
	readonly scrollContainer: HTMLElement | null = $derived(this.#props.getScrollContainer());

	constructor(props: ScrollSpyStateProps) {
		this.#props = props;
	}

	/** Drives each link's `data-state` and `aria-current`. */
	isActive(id: string): boolean {
		return this.value === id;
	}

	/**
	 * Upstream's `store.setState('value', …)` (lines 138-148): equal values are dropped without
	 * notifying, and `onValueChange` fires only for a truthy next value — so seeding or clearing to
	 * `''` is silent.
	 *
	 * What actually landed is read back afterwards, because an authoritative parent bound through
	 * `bind:value={() => …, (next) => …}` may decline the write; a later parent-driven change to the
	 * same id must then still count as external (research R-06).
	 */
	setValue(next: string): void {
		if (Object.is(this.#props.getValue(), next)) return;

		this.#props.setValue(next);
		this.#lastAppliedValue = this.#props.getValue();
	}

	/**
	 * Upstream's `onScrollToSection` (lines 174-219): record the value immediately, scroll the
	 * tracked area to the section's offset-adjusted position, and hold passive tracking off for
	 * {@link SCROLL_SETTLE_DELAY} ms so the scroll's own intersections cannot overwrite the choice.
	 *
	 * A section that is not in the DOM still records the value, and scrolls nothing (**FR-004**).
	 * Rapid repeated clicks each clear the previous timeout, so only the latest window governs.
	 */
	scrollToSection(id: string): void {
		const container = this.scrollContainer;
		const section = container ? container.querySelector(`#${id}`) : document.getElementById(id);

		if (!section) {
			this.setValue(id);
			return;
		}

		this.#isScrolling = true;
		this.setValue(id);

		const behavior = this.scrollBehavior;
		const offset = this.offset;

		if (container) {
			const containerTop = container.getBoundingClientRect().top;
			const sectionTop = section.getBoundingClientRect().top;
			const { scrollTop } = readScrollMetrics(container);

			container.scrollTo({ top: sectionTop - containerTop + scrollTop - offset, behavior });
		} else {
			const sectionTop = section.getBoundingClientRect().top;

			window.scrollTo({ top: sectionTop + window.scrollY - offset, behavior });
		}

		if (this.#settleTimeout !== null) clearTimeout(this.#settleTimeout);

		this.#settleTimeout = window.setTimeout(() => {
			this.#isScrolling = false;
			this.#settleTimeout = null;
		}, SCROLL_SETTLE_DELAY);
	}

	/**
	 * Passive activation from the observer (upstream lines 259-262): suppressed while a click-driven
	 * scroll is settling (**FR-005**), and only ever accepts an element whose id is registered.
	 */
	onObserverTopmost(element: Element): void {
		if (this.#isScrolling) return;

		const id = element.id;
		if (!id || !this.sections.has(id)) return;

		this.setValue(id);
	}

	/**
	 * Upstream's value effect (lines 221-232). The first run only records the seed; every later run
	 * means the value changed from outside the component, so the new section is scrolled to.
	 */
	syncExternalValue(next: string): void {
		if (this.#lastAppliedValue === null) {
			this.#lastAppliedValue = next;
			return;
		}
		if (next === this.#lastAppliedValue) return;

		this.#lastAppliedValue = next;
		this.scrollToSection(next);
	}

	/** Clear the settle timeout. Called from the root's `$effect` teardown (**FR-018**). */
	dispose(): void {
		if (this.#settleTimeout !== null) {
			clearTimeout(this.#settleTimeout);
			this.#settleTimeout = null;
		}
		this.#isScrolling = false;
	}
}

const SCROLL_SPY_CONTEXT_KEY = Symbol('scroll-spy');

export function setScrollSpyContext(state: ScrollSpyState): ScrollSpyState {
	return setContext(SCROLL_SPY_CONTEXT_KEY, state);
}

/**
 * Read the root's state, throwing when there is no `<ScrollSpy.Root>` ancestor (**FR-014**).
 *
 * `consumerName` is the part's short name (`'Nav'`, `'Link'`, `'Viewport'`, `'Section'`) so the
 * message names both the part and its provider, mirroring upstream's `useScrollSpyContext(name)`.
 */
export function getScrollSpyContext(consumerName: string): ScrollSpyState {
	if (!hasContext(SCROLL_SPY_CONTEXT_KEY)) {
		throw new Error(`\`<ScrollSpy.${consumerName}>\` must be used within \`<ScrollSpy.Root>\`.`);
	}
	return getContext<ScrollSpyState>(SCROLL_SPY_CONTEXT_KEY);
}

/**
 * Reusable element-visibility tracking: "which of these elements is topmost inside the viewport".
 *
 * This module is deliberately standalone — it imports nothing from the rest of the `scroll-spy`
 * folder, knows nothing about markup, context or the active value — and is exported from the barrel
 * so the wave-3 `tour` port can consume it directly instead of re-deriving it (research D-6).
 * `pickTopmostEntry`, `observeSections` and `SectionRegistry` are the stability promise to that
 * port: changing their signatures is a breaking change.
 *
 * Ported from `.reference/diceui/docs/registry/bases/radix/ui/scroll-spy.tsx` lines 157-172
 * (the section map) and 234-285 (the observer effect).
 */

/** {@link IntersectionObserverInit} minus the `Document` root upstream never passes. */
export type SectionObserverOptions = {
	/** The element whose box bounds the observation, or `null`/omitted for the viewport. */
	root?: Element | null;
	/** CSS-margin-shaped string shrinking or growing the observation band. */
	rootMargin?: string;
	/** Visible-fraction thresholds at which the observer reports. */
	threshold?: number | number[];
};

/**
 * The intersecting entry with the smallest `boundingClientRect.top`, or `null` when nothing
 * intersects — upstream lines 249-257. Pure: it reads no DOM and mutates nothing, so an empty
 * intersecting set leaves the caller's previous choice standing (spec Edge Case 1).
 */
export function pickTopmostEntry(
	entries: readonly IntersectionObserverEntry[]
): IntersectionObserverEntry | null {
	let topmost: IntersectionObserverEntry | null = null;

	for (const entry of entries) {
		if (!entry.isIntersecting) continue;
		if (!topmost || entry.boundingClientRect.top < topmost.boundingClientRect.top) {
			topmost = entry;
		}
	}

	return topmost;
}

/**
 * Observe `elements` and report the topmost intersecting one, coalescing each callback batch into a
 * single `requestAnimationFrame` so activation cannot flap within a frame (upstream lines 244-247).
 *
 * The returned teardown disconnects the observer, cancels any pending frame, and latches the
 * wrapper closed so a callback that is still in flight can no longer deliver — the caller may have
 * unmounted by then.
 *
 * SSR-guarded: with no `window` or no `IntersectionObserver` it observes nothing and returns a
 * no-op teardown, so a caller never has to branch (the `observeScrollPosition` precedent).
 */
export function observeSections(
	elements: Iterable<Element>,
	onTopmost: (element: Element) => void,
	options: SectionObserverOptions = {}
): () => void {
	if (typeof window === 'undefined' || typeof IntersectionObserver === 'undefined') {
		return () => {};
	}

	let frameId: number | null = null;
	let disposed = false;

	const observer = new IntersectionObserver(
		(entries) => {
			if (disposed) return;

			if (frameId !== null) cancelAnimationFrame(frameId);

			frameId = requestAnimationFrame(() => {
				frameId = null;
				if (disposed) return;

				const topmost = pickTopmostEntry(entries);
				if (!topmost) return;

				onTopmost(topmost.target);
			});
		},
		{
			root: options.root ?? null,
			rootMargin: options.rootMargin,
			threshold: options.threshold
		}
	);

	for (const element of elements) observer.observe(element);

	return () => {
		disposed = true;
		observer.disconnect();
		if (frameId !== null) {
			cancelAnimationFrame(frameId);
			frameId = null;
		}
	};
}

/** One reactive membership snapshot: everything {@link observeSections} needs, read in one pass. */
export type SectionRegistrySnapshot = {
	/** Bumped on every membership change. Reading it subscribes an effect to register/unregister. */
	version: number;
	/** The registered elements, in registration order. */
	elements: Element[];
};

/**
 * The set of elements currently eligible for tracking — upstream's `sectionMapRef` (line 157) plus
 * the reactive version counter Svelte needs.
 *
 * Upstream's observer effect deliberately excludes the section map from its dependencies, which
 * works in React only because child layout effects run before the parent's. Svelte guarantees no
 * such ordering, and FR-018 requires the observer to be re-established whenever the tracked set
 * changes, so membership is a dependency here (divergence D-1, research R-03).
 */
export class SectionRegistry {
	// A plain array of records rather than a `Map`: the storage must stay non-reactive (a reactive
	// map would make `register`'s own lookup a dependency of the effect that calls it), and the
	// section count is small enough that the linear lookups cost nothing.
	#entries: { id: string; element: Element }[] = [];
	#changes = 0;
	#version = $state(0);
	#size = $state(0);

	/** Reactive change counter. Bumped by {@link register} and {@link unregister}. */
	get version(): number {
		return this.#version;
	}

	/** How many elements are registered. Reactive. */
	get size(): number {
		return this.#size;
	}

	/**
	 * Store `element` under `id`. A falsy `id` is never stored (**FR-012**), and re-registering the
	 * same id with the same element does not bump the version — otherwise a section whose
	 * registration effect re-runs with unchanged inputs would re-create the observer forever.
	 */
	register(id: string, element: Element): void {
		if (!id) return;

		const existing = this.#entries.find((entry) => entry.id === id);
		if (existing) {
			if (existing.element === element) return;
			existing.element = element;
		} else {
			this.#entries.push({ id, element });
		}

		this.#bump();
	}

	/** Forget `id`. A no-op — and no version bump — when it was never registered. */
	unregister(id: string): void {
		const index = this.#entries.findIndex((entry) => entry.id === id);
		if (index === -1) return;

		this.#entries.splice(index, 1);
		this.#bump();
	}

	/** Whether `id` is currently tracked. Non-reactive: it gates the observer callback. */
	has(id: string): boolean {
		return this.#entries.some((entry) => entry.id === id);
	}

	/** Read membership reactively. Call this from the effect that owns the observer. */
	snapshot(): SectionRegistrySnapshot {
		return { version: this.#version, elements: this.#entries.map((entry) => entry.element) };
	}

	/**
	 * Both reactive fields are *assigned*, never read-modify-written: the counter is kept in a plain
	 * field, because `this.#version += 1` would make the section's registration effect a dependent of
	 * the very signal it bumps — an effect that reads and writes the same state, i.e. a loop.
	 */
	#bump(): void {
		this.#changes += 1;
		this.#version = this.#changes;
		this.#size = this.#entries.length;
	}
}
